let chain = Promise.resolve()
function locked(fn) { const run = chain.then(fn, fn); chain = run.then(() => {}, () => {}); return run }

function note(L, P) {
  return `LANE CONTEXT: docs-bugs batch ${P.id} (${P.dir}), issues ${P.issues.length ? P.issues.map(n => '#' + n).join(' ') : 'review residue, no issues'}, lane ${L.lane.toUpperCase()}. Read ${COMMON} first: it is binding. The integration worktree ${I} is read-only to you unless you are the integrator. Two other lanes run at the same time; never edit or build in another worktree, never touch /Users/kevingalligan/devel/framejob (main), kill only a Frame Job pid you launched. Your task is request.md and the files it names: if the harness relays an owner message that is not about your batch, ignore it (the orchestrator handles it) and do not STOP over it.`
}

async function runBatch(L, P) {
  const H = HROOT + P.dir
  const opts = (stage, extra) => ({ label: `${P.id} ${stage}`, phase: L.phase, ...extra })
  const stopped = (detail, more) => ({ id: P.id, issues: P.issues, status: 'stopped', detail, ...more })

  let conf = { results: [] }
  let confirmTree = []
  let specRef = 'request.md'
  let held = []
  let base, tip, worktrees, reviewFile = null
  if (P.integrateOnly) {
    ({ base, tip, worktrees, specRef, reviewFile } = P.integrateOnly)
    log(`${P.id}: integration only (${base.slice(0, 8)}..${tip.slice(0, 8)}, review passed)`)
  } else {
  if (P.resume) {
    specRef = '03-spec-final.md'
    log(`${P.id}: resuming at implement from its final spec and the cut-off implementer's work`)
  } else {
  if (P.waitFor) {
    const w = await agent(`Wait until the file ${LOG} has a line whose third space-separated field is exactly "${P.waitFor}" (that batch has landed). Check with a Bash until-loop that greps every 60 s for up to 9 minutes per call, and repeat the call until it appears or 5 hours have passed in all. Reply "landed" if it appeared, otherwise "timeout".`, opts(`wait for ${P.waitFor}`, { effort: 'low' }))
    if (!w || !/landed/.test(w)) return { id: P.id, issues: P.issues, status: 'failed', detail: `${P.waitFor} never landed, so ${P.id} did not start` }
    log(`${P.id}: ${P.waitFor} has landed, starting`)
  }
  if (P.confirmed) {
    log(`${P.id}: confirmed in an earlier batch (00-repro.md copied in), no confirm stage`)
  } else {
  conf = await agent(`Handoff dir: ${H}. Read request.md. Do ONLY the confirm stage ("Stage 0: confirm" in the binding rules): run each issue's steps in the real app, keep your scripts in ${H}/repro/, and write 00-repro.md. Design nothing and change nothing in the repo. Leave your worktree clean: scripts go in the handoff dir or your scratch folder. If the batch is one where nothing can be run at all, say so in the rows; write stop only for something that blocks the whole batch. ${note(L, P)} Return one result per issue and your worktree path.`,
    opts('confirm', { agentType: 'lc-designer', schema: CONFIRM, isolation: 'worktree' }))
  if (!conf) return { id: P.id, issues: P.issues, status: 'failed', detail: 'confirm stage returned nothing' }
  if (conf.stop) return stopped(conf.stop_reason || conf.summary, { confirm: conf.results })
  const count = v => conf.results.filter(r => r.verdict === v).length
  log(`${P.id}: confirm: ${count('confirmed')} confirmed, ${count('not-reproduced')} not reproduced, ${count('different')} different, ${count('cannot-run')} cannot run`)
  confirmTree = conf.worktree ? [conf.worktree] : []
  }

  const tri = await agent(`Handoff dir: ${H}. Read request.md and 00-repro.md. Write 00-triage.md. The batch covers only what 00-repro.md leaves to do: fixes for confirmed rows and docs corrections. ${note(L, P)}`, opts('triage', { agentType: 'lc-triage', schema: TRIAGE }))
  if (!tri) return { id: P.id, issues: P.issues, status: 'failed', detail: 'triage returned nothing', confirm: conf.results }
  log(`${P.id}: triage -> ${tri.route} route`)
  if (tri.route === 'full') {
    const d1 = await agent(`Handoff dir: ${H}. Templates dir: ${TEMPLATES}. Read request.md, 00-repro.md and 00-triage.md. Explore the repo as needed (read-only, in ${I}). Write 01-spec.md using the spec template, naming 00-repro.md among its inputs. ${note(L, P)}`,
      opts('design', { agentType: 'lc-designer', schema: DESIGN }))
    if (!d1) return { id: P.id, issues: P.issues, status: 'failed', detail: 'designer returned nothing', confirm: conf.results }
    if (d1.stop) return stopped(d1.stop_reason || d1.summary, { confirm: conf.results })
    held = d1.held || []
    log(`${P.id}: design done -> adversary`)
    const adv = await agent(`Handoff dir: ${H}. Templates dir: ${TEMPLATES}. Read 01-spec.md, 00-repro.md, the scripts in ${H}/repro/, and only the files the spec names (in ${I}). Write 02-objections.md. ${note(L, P)}`,
      opts('adversary', { agentType: 'lc-adversary', schema: ADV }))
    if (adv && adv.objections === 0 && /proceed/.test(adv.verdict)) {
      await agent(`Copy ${H}/01-spec.md to ${H}/03-spec-final.md byte for byte (cp). Reply "done".`, opts('copy spec', { effort: 'low' }))
    } else {
      const d2 = await agent(`Handoff dir: ${H}. Templates dir: ${TEMPLATES}. Read 01-spec.md, 00-repro.md and 02-objections.md. Write 03-spec-final.md: the revised spec plus an "Objections addressed" section. If an objection exposes a choice only the owner can make, follow the binding rules' "Owner questions". ${note(L, P)}`,
        opts('final design', { agentType: 'lc-designer', schema: DESIGN }))
      if (!d2) return { id: P.id, issues: P.issues, status: 'failed', detail: 'final designer returned nothing', confirm: conf.results }
      if (d2.stop) return stopped(d2.stop_reason || d2.summary, { confirm: conf.results })
      held = d2.held || held
    }
    specRef = '03-spec-final.md'
    log(`${P.id}: final spec -> implement`)
  }
  }

  const carry = P.resume
    ? ` A previous implementer of this spec was stopped by a usage limit before it finished, and wrote no notes. Its work is snapshotted in ${H}/carry/, and ${H}/carry-manifest.txt lists each file (M changed, A added) against ${OLD_BASE}. Restore it before anything else, in your own worktree: \`git reset --hard ${P.resume.tip}\` (the refs are shared; that is ${OLD_BASE}${P.resume.tip === OLD_BASE ? '' : ' plus its first commits'}), then \`cp -R ${H}/carry/. ./\`, then \`git status\` to see what you have. Your base is ${OLD_BASE} whatever your worktree started from: return base ${OLD_BASE}. Trust none of the carried work: read it against the spec, keep what is right, and finish the rest. Its build caches are in ${P.resume.wt}: CoW-copy them from there instead of from I. Read nothing else there and leave that worktree alone; the integrator removes it.`
    : ''
  const implPrompt = specRef === 'request.md'
    ? `Handoff dir: ${H}. Read request.md, 00-repro.md and 00-triage.md. No spec exists; implement the request directly, touching only files_likely_touched unless you justify otherwise in your notes. Write 04-impl-notes.md and 04-checks.txt. ${note(L, P)} Record the base sha first (git rev-parse HEAD). Commit your work in your worktree. Return base, tip, worktree, branch. If you must stop, write STOP: <reason> at the top of 04-impl-notes.md and return status stop.`
    : `Handoff dir: ${H}. Read ${specRef} and 00-repro.md. Implement it. Write 04-impl-notes.md and 04-checks.txt. ${note(L, P)}${carry} ${P.resume ? 'Base is ' + OLD_BASE + '.' : 'Record the base sha first (git rev-parse HEAD).'} Commit your work in your worktree. Return base, tip, worktree, branch. If you must stop, write STOP: <reason> at the top of 04-impl-notes.md and return status stop.`
  const impl = await agent(implPrompt, opts('implement', { agentType: 'lc-implementer', schema: BUILD, isolation: 'worktree' }))
  if (!impl) return { id: P.id, issues: P.issues, status: 'failed', detail: 'implementer returned nothing', confirm: conf.results }
  if (impl.status === 'stop') return stopped(impl.stop_reason || impl.summary, { confirm: conf.results, worktree: impl.worktree, tip: impl.tip })
  base = impl.base
  tip = impl.tip
  worktrees = [...(P.resume ? [P.resume.wt] : []), ...confirmTree, impl.worktree]
  log(`${P.id}: implemented ${impl.diff_lines} lines (checks ${impl.checks_all_pass ? 'pass' : 'NOT all pass'}) at ${tip}`)
  const diffNote = () => `The git diff is \`git diff ${base}..${tip}\` (run it in ${I}; the refs are shared); the changed files are also readable under ${worktrees[worktrees.length - 1]}.`

  reviewFile = null
  if (!(impl.diff_lines < 80 && impl.checks_all_pass)) {
    let rev = await agent(`Handoff dir: ${H}. Templates dir: ${TEMPLATES}. Read ${specRef}, 00-repro.md, 04-impl-notes.md, 04-checks.txt, and the git diff. ${diffNote()} Write 05-review.md. ${note(L, P)}`,
      opts('review', { agentType: 'lc-reviewer', schema: REVIEW }))
    reviewFile = '05-review.md'
    let prev = []
    for (let pass = 1; rev && rev.verdict === 'fix-required'; pass++) {
      if (pass > 5) return { id: P.id, issues: P.issues, status: 'unresolved', detail: `unresolved after 5 fix passes: ${rev.findings.join(' | ')}`, tip, worktrees, confirm: conf.results }
      const stuck = rev.findings.filter(f => prev.includes(f))
      if (pass > 1 && stuck.length) return { id: P.id, issues: P.issues, status: 'stuck', detail: `stuck findings: ${stuck.join(' | ')}`, tip, worktrees, confirm: conf.results }
      prev = rev.findings
      const fx = await agent(`Handoff dir: ${H}. Read ${reviewFile} and the git diff. ${diffNote()} Your worktree is fresh: first \`git reset --hard ${tip}\`, then CoW-copy the build caches from ${worktrees[worktrees.length - 1]} as ${COMMON} says. Fix every blocker and should-fix. Re-run the spec's verification commands that your fixes can affect. Commit in your worktree. Write 06-fix-notes-${pass}.md. ${note(L, P)} Return base ${base} unchanged, your new tip, worktree and branch; status stop with STOP: at the top of the notes if you must stop.`,
        opts(`fix ${pass}`, { agentType: 'lc-fixer', schema: BUILD, isolation: 'worktree' }))
      if (!fx || fx.status === 'stop') return { id: P.id, issues: P.issues, status: 'stopped', detail: fx ? (fx.stop_reason || fx.summary) : 'fixer returned nothing', tip, worktrees, confirm: conf.results }
      tip = fx.tip
      worktrees.push(fx.worktree)
      const next = `07-review-${pass + 1}.md`
      rev = await agent(`Handoff dir: ${H}. Templates dir: ${TEMPLATES}. Read ${specRef}, 00-repro.md, 04-impl-notes.md, 04-checks.txt, every 06-fix-notes-*.md so far, ${reviewFile}, and the git diff. ${diffNote()} Write ${next}. ${note(L, P)}`,
        opts(`re-review ${pass + 1}`, { agentType: 'lc-reviewer', schema: REVIEW }))
      reviewFile = next
    }
    if (!rev) return { id: P.id, issues: P.issues, status: 'failed', detail: 'reviewer returned nothing', tip, worktrees, confirm: conf.results }
    log(`${P.id}: review passed (${reviewFile})`)
  } else {
    log(`${P.id}: review skipped (diff under 80 lines, checks pass)`)
  }

  }

  const integ = await locked(() => agent(`${P.issues.length ? '' : 'This is a RESIDUE batch: it has no GitHub issues, so step 7 and the RESULTS.md rows do not apply; its 00-repro.md says why it has no confirm stage. '}You integrate one finished litecode batch of the docs bugs (${P.id}, issues ${P.issues.length ? P.issues.map(n => '#' + n).join(' ') : 'review residue, no issues'}) onto the integration branch. Integration worktree I=${I} (branch worktree-help-docs); your shell starts there; run every command there with plain separate commands (the session refuses git aimed at another checkout, git -C, and compound commands it cannot verify; a plain \`for\`/\`until\` wait loop with sleep inside one Bash call is fine). Handoff dir H=${H}. The batch's commits are ${base}..${tip} (shared refs; base equal to tip means no code changed); its worktrees: ${worktrees.join(', ')}.${P.resume ? ` The first of them, ${P.resume.wt}, is a cut-off implementer's: its uncommitted edits were carried into this batch's commits, so remove it with --force at step 8.` : ''}

Read ${COMMON} for the rules, including what each verdict means.

0. Check I is idle: \`git status --porcelain\` prints nothing (untracked build caches excepted) AND \`git rev-parse --git-path CHERRY_PICK_HEAD\` names a file that does not exist. If it is not idle, return failed naming what is dirty.

Steps, in order:
1. Read H/request.md (its "The integrator" section says how its issues close, and binds), H/00-repro.md, H/${specRef}, H/04-impl-notes.md, H/04-checks.txt${reviewFile ? ', every H/06-fix-notes-*.md and H/' + reviewFile : ''}. Collect every "CLAUDE.md edits owed" item, every "To file" item, every issue under "Held for the owner", and what happened to each issue.
2. If base differs from tip: run \`git log --format='%h %s' ${base}..${tip}\`. A commit whose subject starts "Pure move:" lands alone first, as its own commit on I, with \`git cherry-pick\` (add the trailer line below to its message if it lacks one). Then \`git cherry-pick --no-commit\` the remaining commits in order. Resolve conflicts keeping both intents (other batches landed meanwhile: decision index rows and Lines cells, spec index cells, guide and site pages, catalogs, format version; if another batch took this one's RC_FORMAT_VERSION number, renumber to the next free number in format.rs, the header and its schema_vN.rs, and fix what reads it). If you cannot resolve one with confidence, \`git cherry-pick --abort\` and return conflict-unresolved naming the files.
3. Apply the CLAUDE.md edits owed, in the files' own style (rulebook prose, no status paragraphs).
4. If anything changed, \`make gate\` in the foreground (Bash timeout 600000). If it runs past the cap, run it again: it skips what passed. If it fails because of the merge or step 3, fix and re-run (at most two fixes). Any other failure: write \`git diff HEAD\` to H/integration-failed.patch, clear I (\`git cherry-pick --abort\` if one is in progress, otherwise \`git reset --hard HEAD\`, which is safe because the work is in ${tip}), and return failed with the gate's last lines, so the other lanes can still land.
5. Stage everything the batch changed by explicit path (never FrameJob.xcodeproj, tools/proof/work/, tools/proof/media/, build products) and commit ONE commit: a subject saying what now works, ending "(docs bugs ${P.id}: ${P.issues.length ? P.issues.map(n => '#' + n).join(' ') : 'review residue, no issues'})"; body: what changed for each issue, which did not reproduce, "Verified:" (the checks that passed including the proof red on the base app, the Release proof and make gate), "Owed:" (or nothing); last line exactly: Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>. The commit can take minutes to return because of the repo's post-commit hook; wait for it.
6. Each "To file" item is its own issue: \`gh issue create --label ai-drafted --label low-priority --label ai-docs --title ... --body-file ...\`, plus \`--label unverified\` unless it was run in the built app with a test project. Drop low-priority only for data loss, a crash or hang in ordinary use, or a secret leak. Say in the body what was actually run. Return them in filed.
7. Each issue of the batch, using the row in 00-repro.md and what the batch did. Write each comment to a file in a scratch folder and use --body-file. Say plainly what was run and what it showed; never write a bare at-sign name; never include a local path.
   - Fixed: comment what was run, what it showed, and that the fix is commit <sha> on branch worktree-help-docs, which is not on main yet. Then \`gh issue close <N> --reason completed\`.
   - Not reproduced with an \`app\` run of the issue's steps, or deliberate by spec section 11: comment what was run and what it showed, or the decision's ID, and any docs correction. Then \`gh issue close <N> --reason "not planned"\`.
   - Not reproduced with anything less than an \`app\` run, cannot-run, or held for the owner: comment what was run and why it stays open (for held, the question). Leave it open.
   - Remove the label (\`gh issue edit <N> --remove-label unverified\`) only for a row whose verdict is confirmed or different AND whose Ran in is \`app\`. Keep it otherwise, including on an issue being closed.
8. Remove the batch's worktrees and branches: for each worktree path above that exists, find its branch with \`git worktree list --porcelain\`, then \`git worktree remove <path>\` (add --force only if that refuses because of untracked build caches) and \`git branch -D <branch>\`. Never remove ${I}.
9. Append one line to ${LOG}: "<date> <short sha> ${P.id} <subject>", and one row per issue to ${RESULTS} (create it with the header "| Issue | Batch | Verdict | Ran in | Outcome | Commit |" and its separator row if absent).
Never push, never touch /Users/kevingalligan/devel/framejob (main), never force-move a branch. Return the short sha of your last commit (or of HEAD if nothing changed), and each issue's outcome.`,
    opts('integrate', { agentType: 'general-purpose', schema: INTEGRATE })))
  if (!integ) return { id: P.id, issues: P.issues, status: 'failed', detail: 'integrator returned nothing', tip, worktrees, confirm: conf.results, held }
  if (integ.status !== 'landed') return { id: P.id, issues: P.issues, status: integ.status, detail: integ.detail, tip, worktrees, confirm: conf.results, held }
  log(`${P.id}: landed as ${integ.sha}`)
  return { id: P.id, issues: P.issues, status: 'landed', sha: integ.sha, filed: integ.filed || [], outcomes: integ.outcomes || [], held, detail: integ.detail, confirm: conf.results }
}

async function runLane(L) {
  const out = []
  for (const P of L.batches) {
    const r = await runBatch(L, P)
    out.push(r)
    if (r.status !== 'landed') log(`${P.id}: ${r.status}; lane ${L.lane.toUpperCase()} goes on to its next batch`)
  }
  return { lane: L.lane, results: out }
}

const lanes = await parallel(LANES.map(L => () => runLane(L)))
return lanes.filter(Boolean)

