320	<script>
321	  const root = document.documentElement;
322	  function press(attr, val) { document.querySelectorAll('[' + attr + ']').forEach(b => b.setAttribute('aria-pressed', String(b.getAttribute(attr) === val))); }
323	  function setTheme(t) { root.dataset.theme = t; press('data-set-theme', t); }
324	  function setPage(p) { root.dataset.page = p; press('data-set-page', p); scrollTo(0, 0); }
325	  function setPalette(p) { if (p) root.dataset.blPalette = p; else delete root.dataset.blPalette; press('data-set-palette', p); }
326	  document.querySelectorAll('[data-set-theme]').forEach(b => b.onclick = () => setTheme(b.dataset.setTheme));
327	  document.querySelectorAll('[data-set-page]').forEach(b => b.onclick = () => setPage(b.dataset.setPage));
328	  document.querySelectorAll('[data-set-palette]').forEach(b => b.onclick = () => setPalette(b.dataset.setPalette));
329	  document.querySelector('[data-toggle-theme]').onclick = () => setTheme(root.dataset.theme === 'dark' ? 'light' : 'dark');
330	  const q = new URLSearchParams(location.search);
331	  if (q.get('theme')) setTheme(q.get('theme'));
332	  if (q.get('page')) setPage(q.get('page'));
333	  if (q.get('palette')) setPalette(q.get('palette'));
334	  if (q.get('bare')) document.querySelector('.review').remove();
335	</script>
